"Begriffe aus deinem Spiel (Orte, Personen, Fachwörter). Taucht ein Begriff in einem Dialog auf, wird er unterstrichen und lässt sich anklicken. Gefundene Einträge sammelt der Spieler im Pausenmenü unter „Glossar“.": "Términos de tu juego (lugares, personas, jerga). Cuando un término aparece en un diálogo, se subraya y se puede pulsar. El jugador reúne las entradas encontradas en el menú de pausa, en “Glosario”.",
