"Beim Sieg ausführen": "Ejecutar al ganar",
"Beim Spielstart erscheint immer das Logo der VN Timeline Engine (Pflicht: mindestens 5 Sekunden, ab 2 Sekunden mit Klick überspringbar). Deine eigenen Logos – Bilder oder Videos – können davor oder danach kommen, so viele du willst.": "Al iniciar el juego siempre aparece el logo de VN Timeline Engine (obligatorio: al menos 5 segundos, se puede saltar con un clic tras 2 segundos). Tus propios logos, imágenes o vídeos, pueden ir antes o después, tantos como quieras.",
"Beim Spielstart erscheint immer kurz das Logo der VN Timeline Engine (Pflicht, ca. 2 Sekunden, mit Klick überspringbar). Dein eigenes Studio-Logo kann davor oder danach kommen.": "Al iniciar el juego siempre aparece brevemente el logo de VN Timeline Engine (obligatorio, unos 2 segundos, se puede saltar con un clic). Tu propio logo de estudio puede ir antes o después.",
