"Clips löschen?": "¿borrar clips?",
"Clips verschieben, am rechten Rand ziehen zum Verlängern, Rechtsklick für mehr. Entf löscht, Strg+Z macht rückgängig.": "Mueve clips, arrastra el borde derecho para alargar, clic derecho para más. Supr borra, Ctrl+Z deshace.",
