"Das": "Eso",
"Das Bild wiederholt sich als Kachel und zieht endlos vorbei, z. B. Wolken, Himmel oder Landschaft aus dem Zugfenster. Gezeichnet wird nur, was im Fenster sichtbar ist. Am schönsten mit Bildern, deren Ränder zusammenpassen.": "La imagen se repite como mosaico y pasa sin fin, p. ej. nubes, cielo o paisaje desde la ventana de un tren. Solo se dibuja lo visible. Queda mejor con imágenes cuyos bordes encajan.",
"Das Engine-Logo ist davon ausgenommen: Es lässt sich immer erst nach 2 Sekunden überspringen.": "El logo del motor es una excepción: solo se puede saltar tras 2 segundos.",
"Das Ergebnis wird aus dem Seed des Durchlaufs und der ID der Quelle berechnet. Zurückladen bringt dieselbe Beute, ein neues Spiel neue.": "El resultado se calcula a partir de la semilla de la partida y el ID de la fuente. Al recargar sale el mismo botín; en una partida nueva, otro.",
"Das Gebäude erscheint erst, wenn irgendwo die Aktion „🏰 Gebäude freischalten“ ausgeführt wird – am einfachsten per Rechtsklick auf ein Hub-Objekt → Bausteine → „Wird gekauft …“.": "El edificio solo aparece cuando en algún sitio se ejecuta la acción “🏰 Desbloquear edificio”; lo más fácil es clic derecho en un objeto del hub → Bloques → “Se puede comprar …”.",
"Das Gebäude ist auf „Durch Aktion“ gestellt, aber keine Aktion „🏰 Gebäude freischalten“ zeigt darauf. Spieler bekommen es nie.": "El edificio está en “Por acción”, pero ninguna acción “🏰 Desbloquear edificio” apunta a él. Los jugadores nunca lo obtienen.",
"Das Grundgerüst (Programm und Browser-Technik) ist bei jedem Windows-Spiel gleich groß, auch bei einem winzigen Spiel. Beim Web-Spiel übernimmt das der Browser.": "La base (programa y tecnología de navegador) tiene el mismo tamaño en cada juego de Windows, incluso en uno diminuto. En el juego web se encarga el navegador.",
"Das Inventar hat eigene Bilder für Fenster und Plätze:": "El inventario tiene sus propias imágenes para la ventana y las casillas:",
"Das Original wurde geändert, seit übersetzt wurde": "El original cambió desde que se tradujo",
"Das Spiel beginnt hier": "El juego empieza aquí",
"Das Spiel bleibt bei dieser Zeile stehen, bis der Spieler etwas getan hat – z. B. das Inventar geöffnet oder etwas angezogen. Gut für Tutorials im eigenen Spiel.": "El juego se queda en esta línea hasta que el jugador haya hecho algo, p. ej. abrir el inventario o ponerse algo. Bueno para tutoriales en tu propio juego.",
"Das Spiel lädt nur die Plugins, die du mitlieferst – unverändert. Fremde oder veränderte Dateien werden ignoriert.": "El juego solo carga los plugins que entregas, sin cambios. Los archivos ajenos o modificados se ignoran.",
"Das Spielsystem „Ausrüstung“ ist aus – unter Spielsysteme → Übersicht einschalten.": "El sistema de juego “Equipo” está desactivado; actívalo en Sistemas de juego → Resumen.",
"Das Sprecher-Skript listet alle Zeilen pro Figur mit ID, damit die Aufnahmen richtig benannt werden.": "El guion de locutores enumera todas las líneas por personaje con ID para que las grabaciones tengan el nombre correcto.",
"Das Update wird im Hintergrund geladen. Du kannst dabei weiterarbeiten.": "La actualización se descarga en segundo plano. Puedes seguir trabajando.",
"Das aktuelle Ziel dauert länger als geplant – alles läuft schneller.": "La meta actual tarda más de lo planeado: todo va más rápido.",
"Das ergibt nur Matsch.": "Eso solo hace papilla.",
"Das funktioniert hier nicht.": "Eso no funciona aquí.",
"Das gehört dir schon.": "Eso ya es tuyo.",
"Das gleiche Geschenk wirkt jedes Mal nur halb so stark": "El mismo regalo funciona solo la mitad de bien cada vez",
"Das ist eine Beispielzeile, damit du siehst, wie die Sprechblase im Spiel wirkt.": "Esta es una línea de ejemplo para que veas cómo queda el bocadillo en el juego.",
"Das ist kein Deckel: Im Spiel steigt der Wert immer bis 100 %. Es fehlen nur noch Stellen, an denen es Punkte gibt. Während du baust, ist das normal.": "Esto no es un tope: en el juego el valor siempre puede subir al 100 %. Solo que aún no hay suficientes lugares que den puntos. Es normal mientras construyes.",
"Das kann man hier nicht benutzen.": "Eso no se puede usar aquí.",
