"Den Keller betreten": "Entrar en el sótano",
"Der Antwort ein Ziel geben.": "Dale un destino a la respuesta.",
"Der Dietrich ist abgerutscht …": "La ganzúa se resbaló …",
"Der Filter färbt Hintergrund und Figuren um. „Rückblende“ bringt Sepia und weiche, helle Ränder mit.": "El filtro cambia el color del fondo y los personajes. “Flashback” añade sepia y bordes suaves y claros.",
"Der Klickpunkt ist die Stelle im Bild, die genau auf das Ziel zeigt, z. B. die Spitze eines Pfeils. Fahre über die Vorschau, um den Zeiger zu sehen.": "El punto de clic es el lugar de la imagen que apunta exactamente al objetivo, p. ej. la punta de una flecha. Pasa el ratón sobre la vista previa para ver el cursor.",
"Der Laden ist leer.": "La tienda está vacía.",
"Der Spieler klickt das Objekt an, bestätigt den Kauf, das Geld wird abgezogen und es passiert, was du hier wählst. Ohne Variablen, ohne Bedingungen.": "El jugador hace clic en el objeto, confirma la compra, se le cobra el dinero y ocurre lo que elijas aquí. Sin variables ni condiciones.",
"Der Windows-Export funktioniert nur in der fertigen Programmversion (.exe).": "La exportación a Windows solo funciona en la versión terminada del programa (.exe).",
"Der verlorene Schlüssel": "La llave perdida",
"Design · Auswahl": "Diseño · Elección",
"Design · Figur": "Diseño · Personaje",
"Design · Hintergrund": "Diseño · Fondo",
"Design · Hub-Hintergrund": "Diseño · Fondo del hub",
"Design · Hub-Objekt": "Diseño · Objeto del hub",
"Design · Menü-Button": "Diseño · Botón del menú",
"Design · Sprechblase": "Diseño · Bocadillo",
"Design ändern …": "Cambiar diseño …",
"Detail-Feld": "Panel de detalles",
"Dialog": "Diálogo",
"Dialog danach einfügen": "Insertar diálogo después de",
"Dialog-Text": "Texto del diálogo",
"Dialog: „": "Diálogo: “",
"Dialoge": "líneas de diálogo",
"Dialoge ab Schritt": "líneas de diálogo desde el paso",
"Dialoge, Ren'Py": "Diálogo, Ren'Py",
"Die 10 größten Dateien": "Los 10 archivos más grandes",
"Die Antwort steht im letzten Schritt der Szene und die Szene hat kein „Danach weiter zu“. Wählt der Spieler sie, ist das Spiel zu Ende.": "La respuesta está en el último paso de la escena y la escena no tiene “Luego continuar a”. Si el jugador la elige, el juego termina.",
"Die Aufnahme ist leer geblieben.": "La grabación quedó vacía.",
"Die Ausrüstung erscheint oben im Inventar (Taste I). Ein Klick auf einen belegten Platz legt den Gegenstand ab. Gibt der Spieler einen getragenen Gegenstand ab, wird er automatisch abgelegt.": "El equipo aparece arriba en el inventario (tecla I). Clic en una ranura ocupada quita el objeto. Si el jugador entrega un objeto equipado, se le quita automáticamente.",
"Die Bühne im Editor ist genau so groß wie später das Spiel. Du kannst das später beim Exportieren noch ändern.": "El escenario del editor es exactamente tan grande como el juego después. Puedes cambiarlo al exportar.",
"Die Datei konnte nicht gelesen werden.": "No se pudo leer el archivo.",
"Die Engine hat erkannt, dass ein Objekt genau diesen Umweg benutzt.": "El motor notó que un objeto usa exactamente este apaño.",
"Die Engine kann sie nicht prüfen. Im Spiel gilt sie deshalb als nicht erfüllt, und was daran hängt, erscheint nie.": "El motor no puede comprobarlo. En el juego cuenta como no cumplido, así que lo que dependa de ello nunca aparece.",
"Die Engine prüft jedes eingeschaltete System, ob es so im Spiel funktionieren kann.": "El motor comprueba cada sistema activado para ver si puede funcionar así en el juego.",
"Die Engine sucht im ganzen Projekt nach der passenden Aktion.": "El motor busca la acción correspondiente en todo el proyecto.",
"Die Engine verfolgt alle Wege ab der Startszene. Kommt sie nirgends bei dieser Szene an, erscheint die Meldung.": "El motor sigue cada camino desde la escena inicial. Si ninguno llega a esta escena, aparece este mensaje.",
"Die Engine zählt alle ♥-Punkte zusammen, die eine Figur im ganzen Spiel bekommen kann – Startwert plus jede Stelle, an der es Punkte gibt. Liegt eine Stufe mit Belohnung darüber, kann kein Spieler sie erreichen.": "El motor suma todos los puntos ♥ que un personaje puede recibir en todo el juego: valor inicial más cada lugar que da puntos. Si un nivel con recompensa es mayor, ningún jugador puede alcanzarlo.",
"Die Figur wird über ihren Namen erkannt (Sprecher = Name der Figur am Clip oder Dateiname).": "El personaje se reconoce por su nombre (hablante = nombre del personaje en el clip o nombre del archivo).",
"Die Kamera bewegt die ganze Bühne: Hintergrund, Figuren und Effekte. Dialog und Buttons bleiben stehen. Mit Parallax-Ebenen (am Hintergrund) entsteht Tiefe.": "La cámara mueve todo el escenario: fondo, personajes y efectos. Diálogos y botones se quedan fijos. Las capas de paralaje (en el fondo) dan profundidad.",
"Die Spielzeit läuft in Tageszeiten. Sie ändert sich nur durch die Aktion „Zeit vergehen lassen“ (z. B. nach einem Job oder beim Schlafen). Prüfen kannst du sie mit der Bedingung „Zeit / Kalender“.": "El tiempo de juego avanza por franjas horarias. Solo cambia con la acción “Dejar pasar el tiempo” (p. ej. tras un trabajo o al dormir). Compruébalo con la condición “Tiempo / calendario”.",
"Die Stelle ist gerade nicht sichtbar – vielleicht erst den richtigen Bereich öffnen.": "Ese lugar no está visible ahora; quizá abre primero la zona correcta.",
"Die Szene auswählen.": "Selecciona la escena.",
"Die Truhe öffnen": "Abrir el cofre",
"Die Vorlage legt ein passendes Skelett über die Figur. Danach ziehst du die Gelenke an die richtigen Stellen und ergänzt Haare, Flügel oder einen Schweif als Kette.": "La plantilla coloca un esqueleto adecuado sobre el personaje. Luego arrastra las articulaciones a su sitio y añade pelo, alas o cola como cadena.",
"Die Vorschau benutzt Bilder aus deinem Projekt, damit du sofort siehst, wie es im Spiel wirkt.": "La vista previa usa imágenes de tu proyecto para que veas al instante cómo queda en el juego.",
"Die Wache bestechen (50 Gold)": "Sobornar al guardia (50 oro)",
"Die Wolken stehen still. Das ändern wir!": "Las nubes están quietas. ¡Cambiemos eso!",
"Dienstag": "Martes",
"Diese Figur hat noch keine Bones.": "Este personaje aún no tiene huesos.",
"Diese Meldung nicht mehr zeigen (unter Fehlerliste wieder einblendbar)": "No volver a mostrar este mensaje (se puede volver a mostrar en la lista de problemas)",
"Diese Sprache gibt es schon": "Este idioma ya existe",
"Diese Szene läuft auch auf schwächeren Rechnern flüssig.": "Esta escena también funciona fluida en ordenadores más débiles.",
"Diese Vorlage gehört auf die Hintergrund-Spur": "Esta plantilla va en la pista de fondo",
"Diese Vorlage gehört auf eine Effekt-Ebene": "Esta plantilla va en una capa de efecto",
