"Doppelklick für neuen Dialog": "Doble clic para una nueva línea de diálogo",
"Doppelklick öffnet eine Szene. Rechtsklick auf eine Szene oder eine Linienbeschriftung für neue Pfade.": "Doble clic abre una escena. Clic derecho en una escena o etiqueta de línea para caminos nuevos.",
"Doppelklick: Farb-/Licht-Ebene · Partikel und Filter aus „Effekte“ links hierher ziehen": "Doble clic: capa de color/luz · arrastra aquí partículas y filtros desde “Efectos” a la izquierda",
"Doppelklick: Kamerafahrt (Zoom, Schwenk, Wackeln) · Vorlagen aus „Effekte“ links": "Doble clic: movimiento de cámara (zoom, paneo, temblor) · plantillas desde “Efectos” a la izquierda",
"Doppelklicke in die Kamera-Spur, um einen Kamera-Clip anzulegen.": "Haz doble clic en la pista de cámara para crear un clip de cámara.",
"Doppelt blinzeln": "Doble parpadeo",
"Download-Seite öffnen": "Abrir página de descarga",
"Dramatischer Zoom": "Zoom dramático",
"Drehen": "Girar",
"Drehung": "Rotación",
"Drehung °": "Rotación °",
"Drei Arten: Idle (Dauer-Schleife einer Figur), Geste (einmalig, z. B. Winken) und Zwischensequenz mit Hintergrund, mehreren Figuren, Kamera und Ton.": "Tres tipos: reposo (bucle continuo de un personaje), gesto (una vez, p. ej. saludar) y cinemática con fondo, varios personajes, cámara y sonido.",
"Drei Stellen: Hier Figuren einschalten. In jeder Antwort steht ein Feld „♥ Beziehung“ (+10 Ray). Und überall unter „Nur wenn“ gibt es „♥ Beziehung … ab Stufe Freund“. Den Bildschirm „Beziehungen“ öffnet der Spieler mit Taste B oder im Pausenmenü.": "Tres sitios: activa aquí los personajes. Cada respuesta tiene un campo “♥ Relación” (+10 Ray). Y en todo “Solo si” hay “♥ Relación … desde la etapa Amigo”. El jugador abre la pantalla “Relaciones” con la tecla B o en el menú de pausa.",
"Druiden-Baum": "Árbol druida",
"Du bist hier": "Estás aquí",
"Du hast die neueste Version.": "Tienes la versión más reciente.",
"Du hast nicht genug für den Einsatz.": "No tienes suficiente para la apuesta.",
"Du hast nichts, was du verschenken könntest.": "No tienes nada que puedas regalar.",
"Du schleppst Krüge, wischst Tische und lächelst freundlich.": "Llevas jarras, limpias mesas y sonríes con amabilidad.",
