"Ebenen & Outfits": "Capas y ropa",
"Ebenen von unten nach oben. Alle Bilder einer Figur sollten gleich groß sein (gleiche Leinwand), damit sie genau übereinander passen.": "Capas de abajo arriba. Todas las imágenes de un personaje deberían tener el mismo tamaño (mismo lienzo) para encajar exactamente.",
"Ebenen-Figur": "Personaje por capas",
"Ebenen-Figuren (Körper, Gesicht, Outfit) legst du oben unter „Figuren“ an.": "Los personajes por capas (cuerpo, cara, ropa) los creas arriba en “Personajes”.",
"Ebenen-Stile & Mischmodus": "Estilos de capa y modo de fusión",
"Echter Zufall": "Azar real",
