"Eigene": "Propio",
"Eigene Bilder (z. B. ein PNG mit Feuerball) erscheinen kurz groß über dem Ziel. So lassen sich alle Effekte austauschen.": "Tus propias imágenes (p. ej. un PNG de una bola de fuego) aparecen un momento en grande sobre el objetivo. Así se puede sustituir cualquier efecto.",
"Eigene Inhalte legst du unter Spielsysteme": "Crea tu propio contenido en Sistemas de juego",
"Eigene Musik für diese": "Música propia para esto",
"Eigene Namensfarbe": "Color de nombre propio",
"Eigene Punkte (z. B. Skillpunkte, Ruhm, Talentpunkte)": "Puntos propios (p. ej. puntos de habilidad, fama, talento)",
"Eigene Schriften": "Fuentes propias",
"Eigene Schriften werden beim Export mitgepackt. Achte darauf, dass die Lizenz der Schrift die Weitergabe in Spielen erlaubt.": "Las fuentes propias se incluyen en la exportación. Asegúrate de que la licencia permite distribuirlas en juegos.",
"Eigene Vorlage": "Plantilla propia",
"Eigenen Punkten": "Puntos propios",
"Eigener Rahmen (PNG)": "Marco propio (PNG)",
"Eigener Ton": "Sonido propio",
"Eigenes": "Propio",
"Eigenes Effekt-Bild (statt Effekt)": "Imagen de efecto propia (en vez del efecto)",
"Eigenes Schwarz-Weiß-Bild": "Imagen propia en blanco y negro",
"Eigenschaften": "Propiedades",
"Ein Bild wird automatisch zerschnitten und gemischt. Ohne eigenes Bild nimmt es den aktuellen Hintergrund.": "Una imagen se corta y se mezcla automáticamente. Sin imagen propia usa el fondo actual.",
"Ein Dietrich könnte helfen.": "Quizá ayude una ganzúa.",
"Ein Gebäude erst nach einem gewonnenen Kampf freischalten.": "Desbloquear un edificio solo tras ganar un combate.",
"Ein Gegner": "Un enemigo",
"Ein Haus kaufen, das danach als neuer Ort auf der Karte erscheint.": "Comprar una casa que luego aparece como lugar nuevo en el mapa.",
"Ein Händler, bei dem man einmalig eine Schatzkarte kaufen kann.": "Un comerciante que vende un mapa del tesoro solo una vez.",
"Ein Keyframe legt fest, wohin sich das Objekt bewegt, wenn der Spieler diesen Schritt erreicht. Die Kurve bestimmt, wie weich es dort ankommt.": "Un fotograma clave fija adónde se mueve el objeto cuando el jugador llega a este paso. La curva decide con qué suavidad llega.",
"Ein Ort, an dem der Spieler frei klickt. Bilder aus der Dateiliste auf die Bühne ziehen, um klickbare Objekte anzulegen.": "Un lugar donde el jugador hace clic libremente. Arrastra imágenes de la lista de archivos al escenario para crear objetos clicables.",
"Ein Projekt ist ein Ordner mit einer": "Un proyecto es una carpeta con un",
"Ein Stammgast lässt Trinkgeld da.": "Un cliente habitual deja propina.",
"Ein Stift dreht sich im Schloss. Klicke (oder drücke Leertaste), wenn er im goldenen Bereich ist. Das Ergebnis landet in einer Variable.": "Una ganzúa gira en la cerradura. Haz clic (o pulsa espacio) cuando esté en la zona dorada. El resultado va a una variable.",
"Ein Verbündeter": "Un aliado",
"Ein Ziel ist in 10 Stunden nicht erreichbar: Kosten, Produktion oder Freischaltung prüfen (ohne Klicken, ohne Skilltrees gerechnet).": "Una meta no se puede alcanzar en 10 horas: revisa costes, producción o desbloqueos (calculado sin clics y sin árboles de habilidades).",
"Ein-/Ausblenden": "Aparecer/desvanecer",
"Einblenden": "Aparecer",
"Einblendung bei Änderung": "Aviso al cambiar",
"Einblendung zeigen (aus = Beziehungen bleiben geheim)": "Mostrar aviso (desactivado = las relaciones quedan en secreto)",
"Einblendungen im Spiel": "Avisos en el juego",
"Eine Antwort, ein Hub-Objekt oder „Danach weiter zu“ auf diese Szene zeigen lassen.": "Haz que una respuesta, un objeto del hub o “Luego continuar a” apunte a esta escena.",
"Eine Datei fehlt": "Falta un archivo",
"Eine Ebene kann einer Variable folgen: Hat die Variante einen passenden „Wert“, wird sie automatisch gewählt (z. B. Outfit = 2 → Rüstung).": "Una capa puede seguir a una variable: si la variante tiene un “valor” que coincide, se elige automáticamente (p. ej. ropa = 2 → armadura).",
"Eine Ebene über den Figuren: Farbe oder Bild mit Mischmodus, Partikel (Regen, Schnee …), ein Filter wie „Rückblende“ oder Augen öffnen/schließen. Fertige Effekte findest du links unter „Effekte“.": "Una capa sobre los personajes: color o imagen con modo de fusión, partículas (lluvia, nieve …), un filtro como “Flashback” o abrir/cerrar los ojos. Los efectos preparados están a la izquierda en “Efectos”.",
"Eine Fähigkeit mit eigenem Ton spielt diesen statt der Standardtöne.": "Una habilidad con sonido propio lo reproduce en vez de los sonidos predeterminados.",
"Eine Spalte = ein Klick des Spielers": "Una columna = un clic del jugador",
"Eine Story-Szene, die startet, wenn man an den Ort kommt und die Bedingungen passen. Pflicht-Ereignisse kommen zuerst (z. B. „Tag 5, morgens, Zuhause → Brief vom König“). Am Ende der Szene „Danach weiter zu“ leer lassen oder „↩ Zurück zum Ort“ wählen.": "Una escena de historia que empieza al llegar al lugar si se cumplen las condiciones. Los eventos obligatorios van primero (p. ej. “Día 5, mañana, casa → carta del rey”). Al final de la escena deja vacío “Luego continuar a” o elige “↩ Volver al lugar”.",
"Eine Wiederholung spielt nur diese Szene und kehrt danach zur Galerie zurück. Spielstand und Werte bleiben unberührt.": "Una repetición solo reproduce esta escena y luego vuelve a la galería. Partida guardada y valores quedan intactos.",
"Eine lange Aufnahme mit vielen Sätzen? „Schneiden“ → „Teile erkennen“ → automatisch auf die Dialoge verteilen.": "¿Una grabación larga con muchas frases? “Cortar” → “Detectar partes” → repartir automáticamente en las líneas de diálogo.",
"Eine neuere Version dieses mitgelieferten Plugins ist da. Du hast die Datei selbst geändert – beim Einspielen gehen deine Änderungen verloren.": "Hay una versión más nueva de este plugin incluido. Cambiaste el archivo tú mismo: al instalarla se descartan tus cambios.",
"Eine „Nur wenn“-Bedingung verweist auf etwas, das es nicht mehr gibt – z. B. eine gelöschte Variable, Figur oder einen Gegenstand.": "Una condición “Solo si” se refiere a algo que ya no existe, p. ej. una variable, personaje u objeto borrado.",
"Einer Variable": "Una variable",
"Einfach: Zutaten rein, fertig": "Sencillo: echar ingredientes, listo",
"Einfügen": "Pegar",
"Eingebaute Spur (kann nicht gelöscht werden)": "Pista integrada (no se puede borrar)",
"Einmal zu und wieder auf": "Cerrar una vez y volver a abrir",
"Einpassen": "Ajustar",
"Einrichten": "Configurar",
"Einrichten – fertig. Im Aufbau erscheint die Bäckerei nach dem Kauf.": "Configurado. La panadería aparece en Construcción tras la compra.",
