"Ereignis": "Evento",
"Ereignis am Ort (gestrichelt grün: zurück)": "Evento en un lugar (verde discontinuo: vuelta)",
"Ereignisse (z. B. Tutorial)": "Eventos (p. ej. tutorial)",
"Ereignisse an Orten": "Eventos en lugares",
"Erfahrung": "experiencia",
"Erfahrung pro Schicht": "Experiencia por turno",
"Erfahrung · Lohn ×": "Experiencia · sueldo ×",
"Erfolg": "Logro",
"Erfolg fehlt": "Falta el logro",
"Erfolg freigeschaltet": "Logro desbloqueado",
"Erfolg-Meldung": "Aviso de logro",
"Erfolg:": "Logro:",
"Erfolge": "Logros",
"Erfolge schalten sich frei, wenn ihre Bedingung erfüllt ist (z. B. „Szene ‚Gutes Ende‘ gesehen“), oder per Aktion „🏆 Erfolg freischalten“. Sie gelten für alle Spielstände. Spieler sehen sie im Hauptmenü (Knopf mit Aktion „Erfolge“) und im Pausenmenü.": "Los logros se desbloquean cuando se cumple su condición (p. ej. “escena ‘Final bueno’ vista”) o con la acción “🏆 Desbloquear logro”. Valen para todas las partidas. Los jugadores los ven en el menú principal (botón con acción “Logros”) y en el menú de pausa.",
"Erfolge öffnen": "Abrir logros",
"Ergebnis": "Resultado",
"Ergebnis in": "Resultado en",
"Ergebnis:": "Resultado:",
"Erhalten": "Recibido",
"Erklärung": "Explicación",
"Erklärung und Beispiele": "Explicación y ejemplos",
"Erklärung …": "Explicación …",
"Erledigt": "Completado",
"Erledigt! Klicken zum Weiterlesen.": "¡Hecho! Haz clic para continuar.",
"Erledigt, wenn": "Completado cuando",
"Erledigt, wenn (ohne Abschnitte)": "Completado cuando (sin secciones)",
"Erreicht die Beziehung den Wert, schickt die Figur eine Nachricht – auf Wunsch mit Bild. Das Bild landet in der Galerie bei dieser Figur und leuchtet dort als „Neu“, bis man es ansieht. Aussehen und Töne: Design → Spielsysteme → „Nachricht einer Figur“.": "Cuando la relación alcanza el valor, el personaje envía un mensaje, con imagen si quieres. La imagen va a la galería bajo este personaje y brilla como “Nuevo” hasta que se ve. Aspecto y sonidos: Diseño → Sistemas de juego → “Mensaje de un personaje”.",
"Erreicht, wenn": "Se alcanza cuando",
"Erscheint, nachdem der Dialog dieses Schritts gelesen wurde. Ohne Ziel geht es in dieser Szene weiter.": "Aparece después de leer la línea de diálogo de este paso. Sin destino, la escena continúa.",
"Erscheint, wenn eine Entscheidung die Zuneigung ändert: Name, Leiste vom alten zum neuen Wert, Pfeil mit Zahl und auf Wunsch das Porträt (aus der Figur oben). Stufenwechsel bekommen eine größere Einblendung.": "Aparece cuando una decisión cambia el afecto: nombre, una barra del valor antiguo al nuevo, una flecha con el número y, si quieres, el retrato (del personaje de arriba). Los cambios de etapa reciben un aviso más grande.",
"Erschrecken": "Sobresalto",
"Ersetzt die Keyframes der betroffenen Knochen.": "Sustituye los fotogramas clave de los huesos afectados.",
