"Fertige Bewegungen": "Movimientos preparados",
"Fertige Bewegungen wie Laufen, Nicken, Winken oder Flügelschlag, Posen speichern und spiegeln, und Zwischensequenzen live einfügen oder als Video rendern.": "Movimientos preparados como andar, asentir, saludar o batir alas; guarda y refleja poses, e inserta cinemáticas en directo o renderízalas como vídeo.",
"Fertige Dialoge als Text einfügen (auch Ren'Py)": "Insertar diálogos terminados como texto (también Ren'Py)",
"Fertige Dialoge einfügen: eine Zeile pro Satz als „Name: Text“, Zeilen ohne Namen sind Erzähler. „> Antwort“ untereinander wird eine Auswahl, „# Titel“ beginnt eine neue Szene. Ren'Py-Skripte werden erkannt (Sprecher-Kürzel aus „define“, menu, label); Bilder, Musik und Sprünge werden übersprungen.": "Inserta diálogos terminados: una línea por frase como “Nombre: Texto”; las líneas sin nombre son narración. Varias líneas “> Respuesta” seguidas forman una elección; “# Título” empieza una escena nueva. Se reconocen guiones de Ren'Py (códigos de hablante de “define”, menu, label, jump); imágenes y música se omiten.",
"Fertige Dialoge einfügen: eine Zeile pro Satz als „Name: Text“, Zeilen ohne Namen sind Erzähler. „> Antwort“ untereinander wird eine Auswahl, „# Titel“ beginnt eine neue Szene. Ren'Py-Skripte werden erkannt (Sprecher-Kürzel aus „define“, menu, label); Sprünge (jump) werden zu Verbindungen, Bilder und Musik werden übersprungen.": "Inserta diálogos terminados: una línea por frase como “Nombre: Texto”; las líneas sin nombre son narración. Varias líneas “> Respuesta” seguidas forman una elección; “# Título” empieza una escena nueva. Se reconocen guiones de Ren'Py (códigos de hablante de “define”, menu, label); los saltos se convierten en conexiones, imágenes y música se omiten.",
