"Früher musste man für einen Kauf zwei Dinge bauen: eine Bedingung „Geld ≥ 500“ und eine Aktion „Geld −500“. Das geht jetzt mit einem Feld: Preis.": "Antes, una compra necesitaba dos cosas: una condición “Dinero ≥ 500” y una acción “Dinero −500”. Ahora basta un campo: el precio.",
