"Fähigkeiten": "Habilidades",
"Färbt Figuren passend zum Hintergrund ein, damit sie nicht wie aufgeklebt wirken.": "Tiñe a los personajes según el fondo para que no parezcan pegados.",
"Füge im Reiter „Beziehungen“ Ray hinzu (Knopf „+ Ray“).": "Añade a Ray en la pestaña “Relaciones” (botón “+ Ray”).",
"Füge oben eine Sprache hinzu (z. B. „en“), dann erscheint daneben eine Spalte zum Übersetzen. Im Spiel kann man die Sprache oben umschalten.": "Añade un idioma arriba (p. ej. “en”) y aparecerá al lado una columna para traducir. En el juego el idioma se cambia arriba.",
"Füge rechts unter „Parallax“ eine zweite Ebene hinzu (+ Ebene) und wähle „Parallax Hügel“.": "Añade una segunda capa a la derecha en “Paralaje” (+ Capa) y elige “Colinas de paralaje”.",
"Führt zu": "Lleva a",
"Füllen": "Relleno",
"Für": "Para",
"Für Beta-Tester und Modder: Taste ^ öffnet im fertigen Spiel die Entwickler-Konsole (Werte setzen, springen …).": "Para probadores beta y modders: la tecla ^ abre la consola de desarrollador en el juego terminado (fijar valores, saltar …).",
"Für Sprecher:": "Para locutores:",
"Für jede Meldung: Position, Animation (auch Zersplittern), Dauer, Text mit Platzhaltern {quest} {reihe} {abschnitt} {figur}, Symbol, Sound oder Jingle. Farben, Rahmen und Hintergrund über „🎨“.": "Para cada mensaje: posición, animación (incluido romper), duración, texto con marcadores {quest} {reihe} {abschnitt} {figur}, icono, sonido o sintonía. Colores, marco y fondo con “🎨”.",
"Für {name} gibt es noch keine ♥-Punkte im Spiel. {levels} wird erst erreichbar, wenn du irgendwo Punkte vergibst.": "Todavía no hay puntos ♥ para {name} en el juego. {levels} solo será alcanzable cuando des puntos en algún sitio.",
