"Gebäude fehlt": "Falta el edificio",
"Gebäude produzieren Rohstoffe, werden ausgebaut, Ziele treiben die Geschichte voran. In Echtzeit, auch bei geschlossenem Spiel oder in Spielzeit. Mit Zeitvorschau.": "Los edificios producen recursos y se mejoran; las metas hacen avanzar la historia. En tiempo real, también con el juego cerrado, o en tiempo de juego. Con previsión de tiempo.",
"Gebäude wird nirgends freigeschaltet": "El edificio nunca se desbloquea",
"Gebäude „{name}“ soll durch eine Aktion freigeschaltet werden, aber das passiert nirgends.": "El edificio “{name}” debería desbloquearse con una acción, pero eso nunca ocurre.",
