"Gegenstände": "objetos",
"Gegenstände ausrüsten: Kleidung, Werkzeug, Schmuck … Jeder Platz trägt einen Gegenstand. Der Spieler rüstet im Inventar aus (Gegenstand anklicken → „Ausrüsten“). Prüfen mit der Bedingung „👕 Trägt Gegenstand“, z. B. für Missionen, Quests oder wie eine Figur reagiert.": "Equipar objetos: ropa, herramientas, joyas … Cada ranura lleva un objeto. El jugador equipa en el inventario (clic en un objeto → “Equipar”). Compruébalo con la condición “👕 Lleva objeto”, p. ej. para misiones o cómo reacciona un personaje.",
"Gegenstände im Kampf": "Objetos en combate",
"Gegenstände mit Haken „verschenkbar“ können Figuren gegeben werden (Aktion „🎁 Geschenk geben lassen“, z. B. an einem Hub-Objekt). Vorlieben legst du pro Kategorie fest, Sonderfälle pro Gegenstand. Der Spieler entdeckt die Vorlieben erst beim Schenken.": "Los objetos marcados como “regalables” se pueden dar a personajes (acción “🎁 Dejar que el jugador regale”, p. ej. en un objeto del hub). Ajusta gustos por categoría y casos especiales por objeto. El jugador descubre los gustos solo al regalar.",
"Gegenstände mit Platz": "Objetos con ranura",
"Gegenstände mit einer Wirkung erscheinen im Kampf unter „Gegenstände“ und werden beim Benutzen verbraucht.": "Los objetos con efecto aparecen en combate en “Objetos” y se gastan.",
"Gegenstände sammeln, Inventar-Menü mit Taste I.": "Recoger objetos, menú de inventario con la tecla I.",
"Gegner": "Enemigos",
"Gegner (bis 6)": "Enemigos (hasta 6)",
