"Gegner sollten nach rechts schauen": "Los enemigos deberían mirar a la derecha",
"Gegner stehen links und schauen nach rechts. Ohne Bild erscheint das Symbol.": "Los enemigos están a la izquierda y miran a la derecha. Sin imagen aparece el icono.",
"Geh zurück zur Lern-Szene, klicke die Auswahl an und gib der ersten Antwort ♥ Ray +10.": "Vuelve a la escena de aprendizaje, haz clic en la elección y da a la primera respuesta ♥ Ray +10.",
"Geh zurück zur Szene „Lernen · Animations-Editor“, wähle Ray und stelle die neue Idle-Animation ein.": "Vuelve a la escena “Aprender · Editor de animación”, selecciona a Ray y pon la nueva animación en reposo.",
