"Geld-Anzeige": "Indicador de dinero",
"Gelenke (weiße Punkte) ziehen, Knochen anklicken zum Auswählen. Entf löscht den gewählten Knochen. Verbundene Gelenke bewegen sich gemeinsam.": "Arrastra articulaciones (puntos blancos), haz clic en huesos para seleccionarlos. Supr borra el hueso seleccionado. Las articulaciones unidas se mueven juntas.",
"Gelten fürs ganze Projekt. Bei einer Figur oder einem einzelnen Meilenstein kannst du eigene Töne wählen – die haben Vorrang.": "Se aplica a todo el proyecto. Para un personaje o un hito concreto puedes elegir sonidos propios, que tienen prioridad.",
"Gelten überall, wo an der Aktion selbst kein Bild gewählt ist. Ein Bild direkt an der Aktion hat immer Vorrang.": "Se aplica donde la acción no tenga imagen propia. Una imagen directamente en la acción siempre tiene prioridad.",
