"Hab an dich gedacht 😊 Schau mal, was ich gefunden habe!": "Pensé en ti 😊 ¡Mira lo que encontré!",
"Hafen": "Puerto",
"Haken setzen, was in die Galerie gehört. Bilder schalten sich frei, sobald sie im Spiel einmal zu sehen waren, Musik beim ersten Abspielen, Szenen beim ersten Besuch. Spieler öffnen die Galerie im Hauptmenü (Knopf mit Aktion „Galerie“) oder im Pausenmenü.": "Marca lo que va a la galería. Las imágenes se desbloquean en cuanto se ven una vez en el juego, la música al sonar por primera vez y las escenas en la primera visita. Los jugadores abren la galería en el menú principal (botón con la acción “Galería”) o en el menú de pausa.",
