"Held fehlt": "Falta el héroe",
"Helden": "Héroes",
"Helden sollten nach links schauen": "Los héroes deberían mirar a la izquierda",
"Helden stehen rechts und schauen nach links. Ohne Bild erscheint das Symbol.": "Los héroes están a la derecha y miran a la izquierda. Sin imagen aparece el icono.",
"Hell": "Claro",
