"Heute hast du": "Hoy ya has regalado",
"Hexenküche": "Cocina de bruja",
"Hieb": "Tajo",
"Hier animierst du Figuren mit ihren Knochenpunkten: als Idle-Schleife (z. B. ungeduldig wippen), als Geste für einen Schritt (z. B. Winken) oder als ganze Zwischensequenz mit Hintergrund, mehreren Figuren, Kamera und Ton. Zwischensequenzen laufen live im Spiel oder werden als Video gerendert.": "Aquí animas personajes con sus puntos de hueso: como bucle en reposo (p. ej. tamborilear impaciente), como gesto de un paso (p. ej. saludar) o como cinemática completa con fondo, varios personajes, cámara y sonido. Las cinemáticas corren en directo en el juego o se renderizan como vídeo.",
"Hier bekommt eine Figur ein Skelett. Wähle ein Bild und eine Körper-Vorlage (Zweibeiner, Vierbeiner, Geflügelt …), dann bewegt sie sich weich.": "Aquí un personaje recibe un esqueleto. Elige una imagen y una plantilla de cuerpo (bípedo, cuadrúpedo, alado …) y se moverá con suavidad.",
"Hier fehlt noch Tiefe …": "Aquí falta algo de profundidad …",
"Hier gestaltest du alles, was vorgefertigt ist: Sprechblasen, Buttons, Fenster, Schriften, Sounds und Mauszeiger.": "Aquí diseñas todo de antemano: bocadillos, botones, ventanas, fuentes, sonidos y cursores.",
"Hier gibt es nichts mehr zu tun.": "Aquí ya no queda nada que hacer.",
"Hier ist nichts mehr.": "Aquí ya no queda nada.",
"Hier kannst du gerade nicht arbeiten.": "Ahora mismo no puedes trabajar aquí.",
"Hier legst du Variablen, Gegenstände, Währungen und Loot-Tabellen an. Benutzt werden sie in den Szenen:": "Aquí creas variables, objetos, monedas y tablas de botín. Se usan en las escenas:",
"Hier liegen alle Szenen deines Spiels. Story-Szenen laufen Schritt für Schritt ab, Hub-Szenen (weißer Punkt) sind Orte zum Herumklicken. Neue legst du mit „+ Story“ und „+ Hub“ an.": "Aquí viven todas las escenas de tu juego. Las escenas de historia van paso a paso; las escenas hub (punto blanco) son lugares para explorar con clics. Crea nuevas con “+ Historia” y “+ Hub”.",
