"Hilfe und Tour": "Ayuda y recorrido",
"Hilfe-Prüfung": "Comprobación de ayuda",
"Hintergrund": "Fondo",
"Hintergrund (Platzhalter, wenn leer)": "Fondo (marcador si está vacío)",
"Hintergrund (auf einen Hintergrund-Clip ziehen)": "Fondo (arrastrar a un clip de fondo)",
"Hintergrund bearbeiten": "Editar fondo",
"Hintergrund dahinter": "Fondo detrás",
"Hintergrund für alle Fenster": "Fondo para todas las ventanas",
"Hintergrund ohne Bild – rechts eins wählen": "Fondo sin imagen: elige uno a la derecha",
"Hintergrund ziehen zum Verschieben, Mausrad zum Zoomen.": "Arrastra el fondo para desplazar, rueda del ratón para el zoom.",
"Hintergrund zieht schnell endlos vorbei, leichtes Rütteln": "El fondo pasa sin fin, con leve traqueteo",
"Hintergrund ·": "Fondo ·",
"Hintergrund, Musik, Titel oder Logo und das Aussehen der Buttons. Im Reiter „Design“ kannst du den Buttons eigene Bilder geben.": "Fondo, música, título o logo y el aspecto de los botones. En la pestaña “Diseño” puedes dar a los botones imágenes propias.",
"Hintergrund-Spur": "Pista de fondo",
"Hintergrundbild rechts wählen": "Elige una imagen de fondo a la derecha",
"Hintergründe automatisch an die Tageszeit anpassen (wenn beim Hintergrund keine eigene Tageszeit gewählt ist)": "Ajustar los fondos a la hora del día automáticamente (si el fondo no tiene hora propia)",
"Hinweis": "Pista",
"Hinweis: Das Skelett gehört zum Bild. Ein neues Bild braucht eigene Bones.": "Nota: el esqueleto pertenece a la imagen. Una imagen nueva necesita sus propios huesos.",
"Hitbox-Form": "Forma de la hitbox",
"Hitboxen anzeigen": "Mostrar hitboxes",
