"Kampf": "Combate",
"Kampf fehlt": "Falta el combate",
"Kampf gewonnen": "Combate ganado",
"Kampf ohne Gegner": "Combate sin enemigos",
"Kampf wie in klassischen Rollenspielen: rundenbasiert, Seitenansicht, Gruppe aus bis zu vier Helden. Gestartet wird ein Kampf mit der Aktion „⚔ Kampf starten“ – an einem Dialog, einer Antwort oder einem Hub-Objekt. Sieg, Niederlage und Flucht führen in eigene Szenen; „⚔ Kampf gewonnen“ fragt das Ergebnis später ab.": "Combate como en los RPG clásicos: por turnos, vista lateral, un grupo de hasta cuatro héroes. Un combate empieza con la acción “⚔ Iniciar combate”, en un diálogo, una respuesta o un objeto del hub. Victoria, derrota y huida llevan a sus propias escenas; “⚔ Combate ganado” comprueba el resultado más tarde.",
"Kampf:": "Combate:",
"Kampf: Startgruppe ist leer": "Combate: el grupo inicial está vacío",
"Kampf: noch keine Helden angelegt": "Combate: aún no hay héroes",
"Kampfmusik": "Música de combate",
"Kampfwert": "valor de combate",
"Kampfwert der Gruppe erhöhen": "Subir un valor de combate del grupo",
"Kann immer wieder gekauft werden": "Se puede comprar una y otra vez",
"Kapitel": "Capítulo",
"Kapitel auflösen (Szenen bleiben)": "Disolver capítulo (las escenas se quedan)",
"Kaputte Bedingung": "Condición rota",
"Kaputte Bedingung ({where}): {what} – gilt im Spiel als nicht erfüllt.": "Condición rota ({where}): {what} – en el juego cuenta como no cumplida.",
"Kaputte Bedingung:": "Condición rota:",
"Kaputte Bedingungen verweisen auf etwas, das es nicht mehr gibt – im Spiel gelten sie als NICHT erfüllt. Dazu Hinweise zu Welt, Orten und Quests.": "Las condiciones rotas hacen referencia a algo que ya no existe: en el juego cuentan como NO cumplidas. Además, avisos sobre mundo, lugares y misiones.",
"Karte": "Mapa",
