"Kartenbild wählen, dann Orte hinzufügen und die Punkte auf der Karte an die richtige Stelle ziehen. Unterkarten (Welt → Stadt → Viertel) öffnen sich per Klick.": "Elige una imagen de mapa, luego añade lugares y arrastra los puntos del mapa a su sitio. Los submapas (mundo → ciudad → barrio) se abren con un clic.",
"Kartenname": "Nombre del mapa",
"Kartenpaare finden – mit deinen eigenen Bildern.": "Encuentra parejas de cartas, con tus propias imágenes.",
"Kartenrückseite": "Reverso de la carta",
