"Kategorien, z. B. Blumen, Süßes": "Categorías, p. ej. flores, dulces",
"Kauf eingerichtet – mit „Spiel testen“ ausprobieren": "Compra configurada: pruébala con “Probar juego”",
"Kaufen": "Comprar",
"Kaufen ohne Umweg": "Comprar sin atajos",
"Kaufen, nur einmal …": "Comprar, solo una vez …",
"Kein Bild": "Sin imagen",
"Kein Hintergrund – rechts einen wählen": "Sin fondo: elige uno a la derecha",
"Kein Job eingerichtet.": "No hay ningún trabajo configurado.",
"Kein Schnellspeicher": "No hay guardado rápido",
"Keine": "Ninguno",
"Keine Aktion": "Sin acción",
"Keine Aktion.": "Sin acción.",
"Keine Antwort, kein „Danach weiter zu“, kein Hub-Objekt und keine Aktion führt vom Start aus zu dieser Szene. Spieler sehen sie nie.": "Ninguna respuesta, ningún “Luego continuar a”, ningún objeto del hub y ninguna acción lleva desde el inicio a esta escena. Los jugadores nunca la verán.",
"Keine Bedingung – immer verfügbar.": "Sin condición: siempre disponible.",
"Keine Gegner": "Sin enemigos",
"Keine Probleme gefunden": "No se encontraron problemas",
"Keine Probleme gefunden. Alles, was die Engine prüfen kann, ist in Ordnung.": "No se encontraron problemas. Todo lo que el motor puede comprobar está bien.",
"Keine Szene zum Abspielen.": "No hay escena para reproducir.",
"Keine Treffer.": "Sin resultados.",
"Keine Verbindung zu GitHub. Prüfe die Internetverbindung oder versuche es später noch einmal.": "No se pudo conectar con GitHub. Comprueba tu conexión a Internet o inténtalo más tarde.",
"Keine Wirkung": "Sin efecto",
"Keine Zeilen gefunden": "No se encontraron líneas",
"Keine Zeit.": "No hay tiempo.",
"Keine Ziele.": "Sin objetivos.",
"Keine Zutaten im Inventar.": "No hay ingredientes en el inventario.",
"Keine einzelnen Geräte gefunden – es wird der System-Standard benutzt.": "No se encontraron dispositivos individuales: se usa el predeterminado del sistema.",
"Keine – von Anfang an kaufbar. Mit „🔗 Verbinden“ auf der Fläche festlegen.": "Ninguno: se puede comprar desde el principio. Se configuran con “🔗 Conectar” en el lienzo.",
"Keiner": "Ninguno",
