"Klar, für dich immer!": "¡Claro, siempre para ti!",
"Klassisch blau (RPG)": "Azul clásico (RPG)",
"Klassisches RPG-Fenster": "Ventana RPG clásica",
"Kleidung": "Ropa",
"Kleidung und Gegenstände ausrüsten (Plätze wie Kopf, Körper, Hand). Für Missionen, Quests oder Figuren, die darauf reagieren.": "Equipar ropa y objetos (ranuras como cabeza, cuerpo, mano). Para misiones, encargos o personajes que reaccionen a ello.",
"Kleine Dialoge, die beim Betreten des Hubs ablaufen, optional mit Spotlight auf ein Objekt.": "Pequeños diálogos que se reproducen al entrar en el hub, opcionalmente con un foco sobre un objeto.",
"Kleine Reise-Animation auf der Karte": "Pequeña animación de viaje en el mapa",
"Kleiner machen": "Más pequeño",
"Klick (Buttons)": "Clic (botones)",
"Klick auf ein Studio-Logo": "Clic en un logo de estudio",
"Klick oder Leertaste, wenn der Stift im goldenen Bereich ist": "Haz clic o pulsa espacio cuando la aguja esté en la zona dorada",
"Klick-Reflex": "Reflejos de clic",
"Klick-Reflex, Memory, Puzzle, Kochen & Brauen, Münzwurf, Blütenblätter zupfen. Jedes liefert ein Ergebnis für Lohn, Beziehung oder Pfad.": "Reflejos de clic, memoria, puzle, cocina y alquimia, cara o cruz, deshojar la margarita. Cada uno da un resultado para paga, relación o ruta.",
"Klick-Regeln": "Reglas de clic",
"Klick: auf-/zuklappen · Rechtsklick: umbenennen, löschen · Szenen hierher ziehen": "Clic: expandir/contraer · Clic derecho: renombrar, borrar · Arrastra escenas aquí",
"Klicke Punkt für Punkt entlang einer Strähne, eines Flügels oder Schweifs. Beginnst du auf einem Gelenk, hängt die Kette daran. Rechts „Kette fertig“ oder Doppelklick.": "Haz clic punto por punto a lo largo de un mechón, ala o cola. Si empiezas en una articulación, la cadena se une a ella. “Terminar cadena” a la derecha o doble clic.",
"Klicke Ray in der Timeline (Figur 1) an.": "Haz clic en Ray en la línea de tiempo (Personaje 1).",
"Klicke Zutaten an, um sie hineinzugeben. Klick im Topf nimmt sie wieder heraus.": "Haz clic en ingredientes para añadirlos. Clic en la olla los vuelve a sacar.",
"Klicke auf den Skill, der vorher gekauft sein muss.": "Haz clic en la habilidad que hay que comprar antes.",
"Klicke den Hintergrund-Clip an.": "Haz clic en el clip de fondo.",
"Klicke die Blütenblätter ab": "Deshojar la margarita",
"Klicke die erste Dialogzeile an.": "Haz clic en el primer diálogo.",
"Klicke einen Knochen an, um Bewegung und Jiggle-Physik einzustellen. Weiße Punkte auf Knochen zeigen, dass Physik aktiv ist.": "Haz clic en un hueso para ajustar movimiento y física de rebote. Los puntos blancos en huesos indican física activa.",
"Klicke einen Skill an, um Name, Kosten, Voraussetzungen und Wirkung einzustellen.": "Haz clic en una habilidad para ajustar nombre, coste, requisitos y efecto.",
"Klicke links auf eine Zeile, um Bedingungen, Belohnungen und Tipps einzustellen.": "Haz clic en una fila a la izquierda para ajustar condiciones, recompensas y pistas.",
"Klicke links unten auf die Spielgröße („Spiel ca. … MB“).": "Haz clic en el tamaño del juego abajo a la izquierda (“Juego aprox. … MB”).",
"Klicke oben über der Bühne auf die Leistungs-Ampel („Leistung: …“).": "Haz clic en el semáforo de rendimiento sobre el escenario (“Rendimiento: …”).",
"Klicke unten in der Timeline auf den Hintergrund-Clip.": "Haz clic en el clip de fondo abajo en la línea de tiempo.",
"Klicke unter der Timeline auf „+ Spur“ und wähle „Figur“.": "Haz clic en “+ Pista” bajo la línea de tiempo y elige “Personaje”.",
