"Mit Bones bewegt sich ein einzelnes Bild sanft: Atmen, Schwanken, Arme schwingen, Haare und Flügel wippen nach.": "Con huesos, una sola imagen se mueve con suavidad: respirar, balancearse, mover los brazos, pelo y alas que rebotan.",
