"Mit dem Werkzeug „Augen“ rahmst du die Augen ein. Dann blinzelt die Figur im Spiel von selbst.": "Con la herramienta “Ojos” enmarcas los ojos. Luego el personaje parpadea solo en el juego.",
"Mit der VN Timeline Engine baust du Visual Novels wie in einem Schnittprogramm: Bilder, Texte und Töne liegen als Clips auf einer Timeline. Das Tutorial-Projekt hat sieben kleine Szenen, jede zeigt genau ein Thema. Diese Tour dauert etwa zwei Minuten.": "Con VN Timeline Engine construyes novelas visuales como en un editor de vídeo: imágenes, textos y sonidos son clips en una línea de tiempo. El proyecto tutorial tiene siete escenas pequeñas y cada una muestra exactamente un tema. Este recorrido dura unos dos minutos.",
"Mit „Zur Stelle“ hinspringen und in der Bedingung das Fehlende neu auswählen.": "Usa “Ir allí” y vuelve a elegir lo que falta en la condición.",
"Mit „Zur Stelle“ hinspringen. Was genau fehlt, steht in der Meldung.": "Usa “Ir allí”. El aviso dice qué falta exactamente.",
