"Noch in keinem Kampf.": "Todavía en ningún combate.",
"Noch kein Name abgefragt: Füge irgendwo die Aktion „✏ Namen eingeben lassen“ hinzu, z. B. an der ersten Dialogzeile.": "Aún no se pide ningún nombre: añade en algún sitio la acción “✏ Dejar que el jugador escriba un nombre”, p. ej. en el primer diálogo.",
"Noch keine": "No",
"Noch keine Audiodateien.": "Aún no hay archivos de audio.",
"Noch keine Audiodateien. Importieren oder hierher ziehen.": "Aún no hay archivos de audio. Impórtalos o arrástralos aquí.",
"Noch keine Bilder im Projekt.": "Aún no hay imágenes en el proyecto.",
"Noch keine Bilder. Importieren oder hierher ziehen.": "Aún no hay imágenes. Impórtalas o arrástralas aquí.",
"Noch keine Ebenen-Figur. Lege eine an: Körper, Gesicht, Kleidung und Accessoires als einzelne Bilder übereinander.": "Aún no hay personaje por capas. Crea uno: cuerpo, cara, ropa y accesorios como imágenes separadas superpuestas.",
"Noch keine Einträge entdeckt.": "Aún no se ha descubierto ninguna entrada.",
"Noch keine Gebäude.": "Aún no hay construcciones.",
"Noch keine Karte angelegt": "Aún no se ha creado ningún mapa",
"Noch keine Plugins im Projekt. Lege das Beispiel-Plugin an, um zu sehen, wie es funktioniert.": "Aún no hay plugins en el proyecto. Crea el plugin de ejemplo para ver cómo funciona.",
"Noch keine Quests. Lege oben eine Quest oder eine Questreihe an.": "Aún no hay misiones. Crea arriba una misión o una serie de misiones.",
"Noch keine Rezepte. Ohne Rezept ergibt Kochen immer „Matsch“.": "Aún no hay recetas. Sin receta, cocinar siempre da “Papilla”.",
"Noch keine Schriften (TTF, OTF, WOFF). Importieren oder hierher ziehen.": "Aún no hay fuentes (TTF, OTF, WOFF). Impórtalas o arrástralas aquí.",
"Noch keine Skills. „+ Skill“ legt einen an, oder starte mit einer Vorlage.": "Aún no hay habilidades. “+ Habilidad” crea una, o empieza con una plantilla.",
"Noch keine Sprecher. Sobald ein Dialog einen Sprecher hat, kannst du ihm hier eine eigene Sprechblase geben.": "Aún no hay hablantes. En cuanto un diálogo tenga hablante, aquí podrás darle su propio bocadillo.",
"Noch keine Videos (WebM, MP4).": "Aún no hay vídeos (WebM, MP4).",
"Noch keine Währung. Lege unter „Währungen“ zum Beispiel „Gold“ an.": "Aún no hay moneda. Crea una en “Monedas”, por ejemplo “Oro”.",
"Noch keine eigenen Schriften. TTF, OTF, WOFF oder WOFF2 importieren oder in die Dateiliste ziehen.": "Aún no hay fuentes propias. Importa TTF, OTF, WOFF o WOFF2 o arrástralas a la lista de archivos.",
"Noch keiner. Unter „Gegenstände“ in der Spalte „Ausrüsten“ einen Platz wählen.": "Aún ninguna. Elige una ranura en “Objetos” en la columna “Equipar”.",
"Noch leer. Am schnellsten geht es mit dem Beispiel: drei Helden, drei Gegner, sechs Fähigkeiten und zwei Kämpfe – alles änderbar.": "Aún vacío. Lo más rápido es empezar con el ejemplo: tres héroes, tres enemigos, siete habilidades y dos combates, todo editable.",
"Noch leer. Am schnellsten geht es mit dem Beispiel: drei Helden, drei Gegner, sieben Fähigkeiten und zwei Kämpfe – alles änderbar.": "Aún vacío. Lo más rápido es empezar con el ejemplo: tres héroes, tres enemigos, siete habilidades y dos combates, todo editable.",
"Noch leer. Das Beispiel „Königreich“ legt Holz und Stein als Rohstoffe an, fünf Gebäude (Holzfällerhütte bis Burg) und drei Ziele – alles änderbar.": "Aún vacío. El ejemplo “Reino” crea madera y piedra como recursos, cinco construcciones (de la cabaña del leñador al castillo) y tres objetivos, todo editable.",
