"Objekte ploppen auf und müssen schnell angeklickt werden. Mit Fallen, die man nicht treffen darf.": "Aparecen objetos que hay que pulsar rápido. Con trampas que no debes tocar.",
"Oder bei einer Antwort, einem Quest-Abschluss oder Aufbau-Ziel die Aktion „🏰 Gebäude freischalten“ hinzufügen.": "O añade la acción “🏰 Desbloquear construcción” a una respuesta, al completar una misión o a un objetivo de construcción.",
