"Oder der Szene ein „Danach weiter zu“ geben.": "O da a la escena un “Luego continuar a”.",
"Oder die Bedingung entfernen, wenn sie nicht mehr gebraucht wird.": "O quita la condición si ya no hace falta.",
"Oder die Meldung für diese Figur ausblenden, solange du noch baust.": "O oculta el aviso para este personaje mientras sigues construyendo.",
"Oder die Stufe niedriger setzen.": "O baja el nivel.",
