"Questreihen bestehen aus Quests, Quests aus Abschnitten. Alles erledigt sich selbst, sobald die Bedingung erfüllt ist („hat Gegenstand Rose“, „Szene gesehen“, „♥ Ray ab Freund“ …) – oder per Aktion „📜 Abschnitt erledigt“ an einer Dialogzeile, Antwort oder einem Hub-Objekt. Spieler öffnen den Questlog mit Taste": "Las series de misiones constan de misiones, y las misiones de secciones. Todo se completa solo en cuanto se cumple la condición (“tiene el objeto rosa”, “escena vista”, “♥ Ray desde Amigo” …), o mediante la acción “📜 Sección hecha” en un diálogo, respuesta u objeto del hub. Los jugadores abren el diario de misiones con la tecla",
"Questreihen, Quests und Abschnitte für Story und Figuren. Erledigen sich selbst über Bedingungen.": "Series de misiones, misiones y secciones para la historia y los personajes. Se completan solas mediante condiciones.",
