"Schalte die Musik-Spur stumm (Maus drüber → M).": "Silencia la pista de música (pasar el ratón → M).",
"Schalte in der Übersicht das Plugin „Jobs“ ein und schau dir den Reiter „Jobs“ an.": "Activa el plugin “Trabajos” en la vista general y mira la pestaña “Trabajos”.",
"Schalte in der Übersicht „Minispiele“ ein, dann kannst du hier eins wählen.": "Activa “Minijuegos” en la vista general y podrás elegir uno aquí.",
"Schalte nur ein, was dein Spiel braucht. Ausgeschaltete Systeme verschwinden aus dem Editor und aus dem Spiel. Eine reine Story-VN braucht keins davon.": "Activa solo lo que necesite tu juego. Los sistemas desactivados desaparecen del editor y del juego. Una VN puramente de historia no necesita ninguno.",
"Schalte „Zeit & Kalender“ ein und gib der ersten Antwort die Aktion „Zeit vergehen lassen“.": "Activa “Tiempo y calendario” y da a la primera respuesta la acción “Dejar pasar el tiempo”.",
