"Sechs Minispiele mit Ergebnis (0–100 % oder geschafft/nicht geschafft): Klick-Reflex, Memory, Puzzle, Kochen & Brauen, Münzwurf, Blütenblätter.": "Seis minijuegos con resultado (0–100 % o éxito/fracaso): reflejos de clic, memoria, puzle, cocina y alquimia, lanzar moneda, pétalos.",
"Sechs Minispiele. Du startest sie über „+ Aktion“ → „Minispiele: …“ – in einer Antwort, an einem Hub-Objekt, in einem Dialog oder als Minispiel eines Jobs. Einstellungen und Bilder wählst du direkt an der Aktion. Jedes Spiel liefert ein Ergebnis von 0–100 % (Feld „Ergebnis in“ → Variable).": "Seis minijuegos. Se inician con “+ Acción” → “Minijuegos: …”, en una respuesta, en un objeto del hub, en un diálogo o como minijuego de un trabajo. Ajustes e imágenes se eligen directamente en la acción. Cada juego devuelve un resultado de 0–100 % (campo “Resultado en” → variable).",
"Sieben Minispiele. Du startest sie über „+ Aktion“ → „Minispiele: …“ – in einer Antwort, an einem Hub-Objekt, in einem Dialog oder als Minispiel eines Jobs. Einstellungen und Bilder wählst du direkt an der Aktion. Jedes Spiel liefert ein Ergebnis von 0–100 % (Feld „Ergebnis in“ → Variable).": "Siete minijuegos. Se inician con “+ Acción” → “Minijuegos: …”, en una respuesta, en un objeto del hub, en un diálogo o como minijuego de un trabajo. Ajustes e imágenes se eligen directamente en la acción. Cada juego devuelve un resultado de 0–100 % (campo “Resultado en” → variable).",
"Sechs fertige Sprechblasen zum Start. Danach lässt sich jede Farbe ändern, ein eigener PNG-Rahmen einsetzen und alles als eigene Vorlage speichern.": "Seis bocadillos listos para empezar. Después puedes cambiar cada color, usar un marco PNG propio y guardarlo todo como plantilla propia.",
