"Setze am Kamera-Clip einen Keyframe bei Schritt 3 und stell dort einen Schwenk ein (Schwenk X).": "Pon un fotograma clave en el paso 3 del clip de cámara y añade ahí un paneo (Paneo X).",
"Setze bei der Wolken-Ebene den Haken „endlos scrollen“.": "Marca “desplazamiento infinito” en la capa de nubes.",
"Sicht der Figur: „Öffnen“ beginnt mit geschlossenen Augen, blinzelt und wird langsam scharf. „Schließen“ endet schwarz, bis der Clip vorbei ist. Testen mit ▶ ab Schritt.": "Punto de vista del personaje: “Abrir” empieza con los ojos cerrados, parpadea y se enfoca despacio. “Cerrar” termina en negro hasta que acaba el clip. Prueba con ▶ desde el paso.",
