"Skills mit Geld oder Punkten freischalten: mehr Verdienst, Rabatt, bessere Minispiele, Werte, freigeschaltete Orte und Quests. Grundlage für inkrementelle Spiele.": "Desbloquea habilidades con dinero o puntos: más ganancias, descuentos, mejores minijuegos, valores, lugares y misiones desbloqueados. La base de los juegos incrementales.",
