"Skilltrees: Spieler verdienen Geld oder Punkte und schalten damit Skills frei, die sofort wirken – mehr Geld, bessere Minispiele, Rabatt, mehr Beziehungspunkte, höhere Werte oder freigeschaltete Orte und Quests. Abfragen lassen sie sich überall mit der Bedingung „🌳 Skill gekauft“. Im Spiel öffnet Taste": "Árboles de habilidades: los jugadores ganan dinero o puntos y desbloquean habilidades que actúan al instante: más dinero, mejores minijuegos, descuentos, más puntos de relación, valores más altos o lugares y misiones desbloqueados. Compruébalas en cualquier sitio con la condición “🌳 Habilidad comprada”. En el juego, tecla",
