"Tiefe 1 = bewegt sich wie die Figuren, 0 = steht still, über 1 = Vordergrund, der schneller vorbeizieht.": "Profundidad 1 = se mueve como los personajes, 0 = quieto, más de 1 = primer plano que pasa más rápido.",
"Tiefe des Hintergrunds": "Profundidad del fondo",
"Tipp": "Consejo",
"Tipp für den Spieler (optional)": "Consejo para el jugador (opcional)",
"Tipp:": "Consejo:",
"Tipp: Auf gebaute Gebäude klicken bringt sofort etwas.": "Consejo: hacer clic en construcciones terminadas da algo al instante.",
"Tipp: Beim Testen öffnet die Taste ^ (oder F12) die Entwickler-Konsole mit echten Bildern pro Sekunde.": "Consejo: al probar, la tecla ^ (o F12) abre la consola de desarrollador con los fotogramas por segundo reales.",
"Tipp: Das Rechteck darf etwas größer als der geschlossene Mund sein. Es öffnet sich von oben nach unten.": "Consejo: el rectángulo puede ser algo más grande que la boca cerrada. Se abre de arriba abajo.",
"Tipp: Eine Antwort „Schlafen gehen“ mit der Aktion „Zeit vergehen lassen → nächster Tag“ und Hub-Objekte mit der Bedingung „Tageszeit ist Abend“ – fertig ist ein Tagesablauf.": "Consejo: una respuesta “Ir a dormir” con la acción “Dejar pasar el tiempo → día siguiente” y objetos del hub con la condición “momento del día es tarde”, y ya tienes una rutina diaria.",
"Tipp: Figuren lassen sich auf der Bühne auch direkt ziehen – waagerecht für die Position, senkrecht für die Höhe (Umschalt: nur eine Richtung).": "Consejo: también puedes arrastrar personajes directamente en el escenario: en horizontal para la posición, en vertical para la altura (Mayús: solo una dirección).",
"Tipp: Mit dem Setup (VN-Timeline-Engine-Setup.exe) kommen Updates automatisch und laden nur die Änderungen. Deine Projekte bleiben dabei, wo sie sind.": "Consejo: con el instalador (VN-Timeline-Engine-Setup.exe), las actualizaciones llegan solas y solo se descarga lo que cambió. Tus proyectos se quedan donde están.",
"Tipp: Mit „100× simulieren“ siehst du, wie schwer der Kampf ist.": "Consejo: “Simular 100×” muestra lo difícil que es el combate.",
"Tipp: Schreibt der Held seine Stufe in eine Variable, kann ein Skilltree bei jedem Stufenaufstieg Punkte geben.": "Consejo: si el héroe guarda su nivel en una variable, un árbol de habilidades puede dar puntos en cada subida de nivel.",
"Tipp: So kannst du z. B. Vorschau-Töne über Kopfhörer hören und das Test-Spiel über die Boxen. Spieler stellen ihr Gerät im fertigen Spiel unter Einstellungen → Tonausgabe selbst ein.": "Consejo: así puedes oír los sonidos de vista previa en los auriculares y el juego de prueba en los altavoces. Los jugadores eligen su dispositivo en el juego terminado en Ajustes → Salida de sonido.",
