"Variablen merken sich, was im Spiel passiert ist: Zahlen (z. B. Vertrauen) oder Schalter (z. B. „Tür geöffnet“). Ändern lassen sie sich mit Aktionen, prüfen mit Bedingungen.": "Las variables recuerdan lo que pasó en el juego: números (p. ej. confianza) o interruptores (p. ej. “puerta abierta”). Se cambian con acciones y se comprueban con condiciones.",
"Variablen, Gegenstände und Geld legst du oben unter „Spielsysteme“ an.": "Crea variables, objetos y dinero arriba en “Sistemas de juego”.",
"Variablen, Gegenstände, Geld, Loot und Plugins. Benutzt werden sie überall als „Wenn → Dann“, zum Beispiel in Szene „05 Wenn → Dann“.": "Variables, objetos, dinero, botín y plugins. Se usan en todas partes como “Si → Entonces”, por ejemplo en la escena “05 Si → Entonces”.",
