"Was passiert, wenn der Spieler diesen Gegenstand anzieht oder ablegt – z. B. „Verkleidet: Jetzt darf ich ins Labor“ (Ort freischalten, Quest-Abschnitt erledigt, Beziehungspunkte). Für „nur verkleidet hinein“ an der Tür die Bedingung „👕 Trägt Gegenstand“ nutzen.": "Qué pasa cuando el jugador se pone o se quita este objeto, p. ej. “Disfrazado: ahora puedo entrar al laboratorio” (desbloquear un lugar, completar un paso de misión, puntos de relación). Para “solo disfrazado” en una puerta, usa la condición “👕 Lleva objeto”.",
