"Wolken, Himmel oder eine Zugfahrt endlos vorbeiziehen lassen.": "Haz pasar sin fin nubes, cielo o un viaje en tren.",
"Womit kombinieren? Zweiten Gegenstand anklicken.": "¿Combinar con qué? Haz clic en el segundo objeto.",
"Wähle Ray und klicke „▶ Bewegung“, um das Atmen zu sehen. Dann wieder stoppen.": "Selecciona a Ray y haz clic en “▶ Movimiento” para ver la respiración. Luego detenlo otra vez.",
"Wähle das Werkzeug „Gewichte malen“ und klicke einen Arm-Knochen an.": "Elige la herramienta “Pintar pesos” y haz clic en un hueso del brazo.",
