"Wähle oben im Lineal einen Schritt innerhalb dieses Clips.": "Elige en la regla de arriba un paso dentro de este clip.",
"Wähle oben „Augen markieren“ und ziehe ein Rechteck um jedes Auge. Oder nimm ein Bild mit geschlossenen Augen.": "Elige arriba “Marcar ojos” y arrastra un rectángulo alrededor de cada ojo. O usa una imagen con los ojos cerrados.",
