"Zieh an den runden Griffen der Knochen. An der Abspielposition entsteht automatisch ein Keyframe. Die Zwiebelhaut zeigt die Pose davor und danach.": "Arrastra los tiradores redondos de los huesos. Se crea automáticamente un fotograma clave en el cabezal. La piel de cebolla muestra la pose de antes y después.",
"Zieh ein Rechteck um den Mund der Figur.": "Arrastra un rectángulo alrededor de la boca del personaje.",
"Zieh im Bild ein Rechteck um den Mund. Im Spiel öffnet und schließt er sich dann nach der Lautstärke der Sprachaufnahme. Ohne Aufnahme bewegt er sich, solange der Text getippt wird.": "Arrastra un rectángulo alrededor de la boca en la imagen. En el juego se abre y cierra con el volumen de la grabación de voz. Sin grabación se mueve mientras se escribe el texto.",
"Ziehe die Wache (links unter Bilder) auf die neue Figur-Spur.": "Arrastra al guardia (a la izquierda en Imágenes) a la nueva pista de personaje.",
