"„+ Neues Plugin“ legt eine Vorlage an, „Code bearbeiten“ öffnet den eingebauten Editor. Die Anleitung steht in PLUGINS.md.": "“+ Nuevo plugin” crea una plantilla, “Editar código” abre el editor integrado. La guía está en PLUGINS.md.",
"„Auf Preis umstellen“ drücken – Bedingung und Geld-Aktion werden durch den Preis ersetzt.": "Pulsa “Cambiar a precio”: la condición y la acción de dinero se sustituyen por el precio.",
"„Fortsetzen“ lädt den neuesten Spielstand und ist ausgegraut, solange es keinen gibt. „Beenden“ schließt das fertige Spiel, beim Testen geht es zurück zum Editor.": "“Continuar” carga la última partida guardada y está en gris mientras no haya ninguna. “Salir” cierra el juego terminado; al probar vuelve al editor.",
"„Liebt mich, liebt mich nicht“ – die Blattzahl sorgt für ein echtes 50:50.": "“Me quiere, no me quiere”: el número de pétalos da un verdadero 50:50.",
"„Menü testen“ zeigt das Menü so, wie es der Spieler sieht.": "“Probar menú” muestra el menú exactamente como lo ve el jugador.",
"„Neu“ zeigen als": "Mostrar “Nuevo” como",
"„Szene testen“ spielt die offene Szene ab dem gewählten Schritt. „Spiel testen“ startet alles mit Hauptmenü, genau wie später beim Spieler.": "“Probar escena” reproduce la escena abierta desde el paso elegido. “Probar juego” empieza todo con el menú principal, igual que para el jugador después.",
"„{name}“ ist ein Ausrüstungs-Gegenstand. Zum Anziehen besser „👕 Trägt Gegenstand“ nehmen – „benutzt“ heißt: im Inventar auf „Benutzen“ geklickt.": "“{name}” es un objeto de equipo. Para ponérselo, mejor usa “👕 Lleva objeto”: “usado” significa que se pulsó “Usar” en el inventario.",
"„{name}“ verbinden mit …": "Conectar “{name}” con …",
"„{name}“ wird gekauft": "“{name}” se puede comprar",
"„{obj}“ in „{scene}“ prüft Geld und zieht es dann ab. Dafür gibt es jetzt den Preis direkt am Objekt – mit Rückfrage und Meldung bei zu wenig Geld.": "“{obj}” en “{scene}” comprueba el dinero y luego lo cobra. Ahora hay un precio directamente en el objeto para eso, con confirmación y un aviso cuando no hay suficiente dinero.",
