"Verknüpfte Szene": "Escena vinculada",
"Von": "Por",
"Vorschau: Spiel mit den Augen farbenblinder Spieler sehen": "Vista previa: ver el juego con los ojos de jugadores daltónicos",
"Weniger Effekte": "Menos efectos",
"Wähle, was übertragen wird. Alles, was nicht angehakt ist, bleibt wie es ist.": "Elige qué se transfiere. Todo lo no marcado se queda como está.",
"Ziehe Bilder aus der Dateiliste links hierher, Doppelklick legt eine Notiz an.": "Arrastra aquí imágenes de la lista de archivos de la izquierda; doble clic crea una nota.",
"Ziehen = Größe ändern": "Arrastrar = cambiar tamaño",
"Ziehen = drehen (Umschalt: 15°-Schritte) · Doppelklick = gerade": "Arrastrar = girar (Mayús: pasos de 15°) · doble clic = recto",
"Ziehen = verschieben · Ecke = Größe · Doppelklick = Text bearbeiten · Rechtsklick = Farbe, Pfeil, Szene · leere Fläche ziehen = Ansicht verschieben · Strg + Mausrad = Zoom · Entf = löschen": "Arrastrar = mover · esquina = tamaño · doble clic = editar texto · clic derecho = color, flecha, escena · arrastrar zona vacía = desplazar · Ctrl + rueda = zoom · Supr = borrar",
"Zum Beispiel „✔ Spieler hat … eine Szene gesehen“ oder eine Variable, die ein Dialog setzt. Danach läuft der Aufbau dauerhaft.": "Por ejemplo “✔ El jugador ha … visto una escena” o una variable que fija un diálogo. Después la construcción sigue en marcha.",
