"Führt im Spiel die Aktionen aus.": "Ejecuta las acciones en el juego.",
"Ein Handy oder ein Computer im Spiel: Startbildschirm mit Apps wie Nachrichten, Inventar, Beziehungen, Galerie, Quests oder eigenen Apps (Seiten, Aktionen, Sprung in eine Szene). Öffnen per Knopf, Taste oder mit der Aktion „📱 Gerät öffnen“ – z. B. auf einer Hitbox im Hub (der Laptop auf dem Schreibtisch).": "Un móvil o un ordenador dentro del juego: una pantalla de inicio con apps como mensajes, inventario, relaciones, galería, misiones o apps propias (páginas, acciones, saltar a una escena). Se abre con un botón, una tecla o la acción “📱 Abrir dispositivo”, p. ej. en una hitbox del hub (el portátil en el escritorio).",
"Noch kein Gerät. Lege oben ein Handy oder einen Computer an.": "Aún no hay dispositivo. Añade arriba un móvil o un ordenador.",
