"Reihenfolge wie auf dem Gerät. Symbol: Emoji oder eigenes Bild. Mit 🔒 erscheint eine App erst, wenn ihre Bedingungen erfüllt sind.": "Mismo orden que en el dispositivo. Icono: emoji o imagen propia. Con 🔒 una app solo aparece cuando se cumplen sus condiciones.",
