"Das System dazu ist ausgeschaltet – die App wird nicht angezeigt.": "Su sistema de juego está desactivado: la app no se muestra.",
"Notizen": "Notas",
"App hinzufügen …": "Añadir app …",
"System aus": "sistema desactivado",
"Im Spiel öffnen": "Abrirlo en el juego",
"Knopf oben rechts, Taste oder Pausenmenü (siehe „Gerät“). In der Story oder im Hub: Aktion „📱 Gerät öffnen“, z. B. an einem Hub-Objekt (Hitbox) – optional direkt in einer App oder einem Chat. Eingebaute Apps öffnen ihren Bildschirm und kehren danach zum Gerät zurück.": "Botón arriba a la derecha, tecla o menú de pausa (ver “Dispositivo”). En la historia o en el hub: acción “📱 Abrir dispositivo”, p. ej. en un objeto del hub (hitbox), opcionalmente directo a una app o a un chat. Las apps integradas abren su pantalla y luego vuelven al dispositivo.",
"Zu den Nachrichten →": "A los mensajes →",
"Vorschau (klickbar)": "Vista previa (clicable)",
"In der Vorschau sind alle Unterhaltungen schon angekommen. Eingebaute Apps und Aktionen laufen erst im Spiel.": "En la vista previa ya han llegado todas las conversaciones. Las apps integradas y las acciones solo funcionan en el juego.",
"Eine eigene App zeigt eine Seite (z. B. Notizen, eine E-Mail, eine Webseite, ein Foto) und/oder führt Aktionen aus. Mit „➜ Zu Szene oder Hub wechseln“ schließt sich das Gerät und die Szene startet.": "Una app propia muestra una página (p. ej. notas, un correo, una web, una foto) y/o ejecuta acciones. Con “➜ Ir a escena o hub” el dispositivo se cierra y empieza la escena.",
"Titel der Seite": "Título de la página",
"Beim Öffnen ausführen": "Ejecutar al abrir",
"Chats bleiben über alle Szenen erhalten. Eine Unterhaltung kommt automatisch an (sobald ihre Bedingungen stimmen) oder per Aktion „💬 Nachricht schicken“. Zeilen mit 🔒 kommen nur, wenn ihre Bedingungen erfüllt sind – so bekommt jede Route ihre eigene Version. Antworten wählt der Spieler; sie können Aktionen ausführen und zur nächsten Unterhaltung führen.": "Los chats se conservan en todas las escenas. Una conversación llega automáticamente (en cuanto se cumplen sus condiciones) o con la acción “💬 Enviar mensaje”. Las líneas con 🔒 solo llegan cuando se cumplen sus condiciones, así cada ruta tiene su propia versión. El jugador elige las respuestas; pueden ejecutar acciones y llevar a la siguiente conversación.",
"Kein Gerät hat die App „Nachrichten“. Unter „Geräte“ hinzufügen.": "Ningún dispositivo tiene la app “Mensajes”. Añádela en “Dispositivos”.",
"Meldung bei neuer Nachricht (Klick öffnet den Chat)": "Aviso de mensajes nuevos (clic abre el chat)",
"Ton bei neuer Nachricht": "Sonido de mensajes nuevos",
"— wie Beziehungs-Meldung —": "— como el aviso de relación —",
"Chat-Zeilen in der Timeline (Dialog „Als Handy-Nachricht zeigen“) landen ebenfalls im Verlauf, wenn der Sprecher ein Kontakt ist – und ältere Nachrichten erscheinen dort darüber.": "Las líneas de chat de la línea de tiempo (diálogo “Mostrar como mensaje de móvil”) también se añaden al historial cuando el hablante es un contacto, y los mensajes anteriores aparecen encima.",
