"Leertaste, Enter oder Klick": "Espacio, Enter o clic",
"Treffer!": "¡Acierto!",
"Daneben!": "¡Fallo!",
"Perfekt – kein Fehler!": "¡Perfecto, sin fallos!",
"Ein Zeiger dreht sich – im richtigen Moment drücken, wenn er in der markierten Fläche steht. Die Fläche springt nach jedem Treffer weiter. Leichter durch Skilltree-Perks, Ausrüstung oder einen Hilfs-Gegenstand.": "Una aguja gira: pulsa en el momento justo mientras esté dentro de la zona marcada. La zona salta a otro sitio tras cada acierto. Más fácil con ventajas del árbol de habilidades, equipo o un objeto de ayuda.",
"Schwierigkeit, Tempo, Größe der Fläche, Treffer, Fehlversuche, schneller werden, Richtungswechsel, Zeitlimit, Hilfs-Gegenstand, eigene Bilder": "Dificultad, velocidad, tamaño de la zona, aciertos, fallos, aceleración, cambio de dirección, límite de tiempo, objeto de ayuda, imágenes propias",
"Sieben Minispiele mit Ergebnis (0–100 % oder geschafft/nicht geschafft): Klick-Reflex, Memory, Puzzle, Kochen & Brauen, Münzwurf, Blütenblätter, Quicktime-Kreis.": "Siete minijuegos con resultado (0–100 % o ganado/perdido): reflejos de clic, memoria, puzle, cocina y alquimia, lanzar moneda, pétalos, círculo quicktime.",
"Erscheint auf": "Aparece en",
"allen Geräten": "todos los dispositivos",
"Unterhaltung „{t}“ ist nur für Geräte ohne App „Nachrichten“ bestimmt – sie wäre nirgends zu lesen.": "La conversación “{t}” solo está pensada para dispositivos sin la app “Mensajes”: no se podría leer en ningún sitio.",
"still (versteckt)": "silenciosa (oculta)",
"Keine Meldung und keine Ungelesen-Zahl – der Spieler findet die Nachricht nur, wenn er selbst nachsieht (z. B. versteckte Mails auf einem PC).": "Sin aviso ni contador de no leídos: el jugador solo encuentra el mensaje buscando (p. ej. correos ocultos en un PC).",
