"Code": "Código",
"z. B. 1234 oder Drache": "p. ej. 1234 o dragón",
"Nur Ziffern = Zahlenfeld, sonst Passwort-Feld. Auch {Platzhalter} einer Variable möglich.": "Solo dígitos = teclado numérico; si no, un campo de contraseña. También vale un {placeholder} de una variable.",
"Einmal richtig eingeben, danach immer offen": "Introducir bien una vez y luego siempre abierto",
"Jedes Mal eingeben": "Introducir cada vez",
"z. B. Geburtstag von Cloe": "p. ej. el cumpleaños de Cloe",
"Ohne Code ist das Gerät nicht gesperrt.": "Sin código el dispositivo no está bloqueado.",
"Prüfen mit der Bedingung „🔓 Gerät entsperrt“. Findet der Spieler den Code in der Story, kann die Aktion „🔓 Gerät entsperren“ ihn auch direkt freischalten.": "Compruébalo con la condición “🔓 Dispositivo desbloqueado”. Si el jugador encuentra el código en la historia, la acción “🔓 Desbloquear dispositivo” puede desbloquearlo directamente.",
"Falscher Code": "Código incorrecto",
"Passwort": "Contraseña",
"Anmelden": "Iniciar sesión",
"Entsperren": "Desbloquear",
"🔓 Gerät entsperrt": "🔓 Dispositivo desbloqueado",
"🔓 Gerät entsperren": "🔓 Desbloquear dispositivo",
"entsperrt": "desbloqueado",
"Beim Lesen dieser Nachricht ausführen (z. B. Ort freischalten)": "Ejecutar al leer este mensaje (p. ej. desbloquear un lugar)",
"Regen, Schnee, Staub, Funken, Blütenblätter oder Glühwürmchen über dem ganzen Hub.": "Lluvia, nieve, polvo, chispas, pétalos o luciérnagas sobre todo el hub.",
"Nur wenn … (z. B. Tageszeit Nacht, Jahreszeit Winter)": "Solo si … (p. ej. momento del día noche, estación invierno)",
"Partikel nur, wenn …": "Partículas solo si …",
"Partikel hinzufügen …": "Añadir partículas …",
"Mit 🔒 z. B. Glühwürmchen nur nachts oder Schnee nur im Winter. Wechselt, sobald im Hub Zeit vergeht.": "Con 🔒, p. ej. luciérnagas solo de noche o nieve solo en invierno. Cambia en cuanto pasa el tiempo en el hub.",
"Beim Betreten des Hubs": "Al entrar en el hub",
"Sobald „Nur wenn“ stimmt (auch mitten im Hub)": "En cuanto se cumpla “Solo si” (también estando en el hub)",
"Nur einmal": "Solo una vez",
"Jedes Mal": "Cada vez",
"Höchstens … mal": "Como máximo … veces",
"Einmal pro Tag": "Una vez al día",
"Gerät „{d}“ nutzt die Taste H – die ist auch „🏠 Zuhause“ bei Welt & Orte. Andere Taste wählen, z. B. P.": "El dispositivo “{d}” usa la tecla H, que también es “🏠 Casa” en Mundo y lugares. Elige otra tecla, p. ej. P.",
"Aus der Liste nehmen (der Ordner bleibt)": "Quitar de la lista (la carpeta se queda)",
"Desktop-Version herunterladen": "Descargar la versión de escritorio",
"Die Windows-Version eines Spiels lässt sich nur mit der Desktop-Version der Engine bauen. Im Browser: Web-Export (ZIP, z. B. für itch.io).": "La versión de Windows de un juego solo se puede crear con la versión de escritorio del motor. En el navegador: exportación web (ZIP, p. ej. para itch.io).",
"Ein Projektordner (mit project.json) – Änderungen werden direkt dort gespeichert, wie in der Desktop-Version.": "Una carpeta de proyecto (con project.json): los cambios se guardan ahí mismo, como en la versión de escritorio.",
"In der ZIP-Datei ist kein Projekt (project.json fehlt).": "El archivo ZIP no contiene ningún proyecto (falta project.json).",
"In diesem Projekt fehlt die project.json.": "Este proyecto no tiene project.json.",
"Läuft ohne Installation. Projekte werden in diesem Browser gespeichert – lade sie über „Projekt ▾ → Als ZIP herunterladen“ als Sicherung herunter.": "Funciona sin instalar. Los proyectos se guardan en este navegador: descárgalos como copia con “Proyecto ▾ → Descargar como ZIP”.",
"Noch keine Projekte in diesem Browser.": "Aún no hay proyectos en este navegador.",
"Ordner auf dem PC": "Carpeta en el PC",
"Ordner auf dem PC öffnen …": "Abrir una carpeta del PC …",
"Projekt löschen": "Borrar proyecto",
"Projekt „{n}“ endgültig aus diesem Browser löschen? Lade es vorher als ZIP herunter, wenn du es behalten willst.": "¿Borrar para siempre el proyecto “{n}” de este navegador? Descárgalo antes como ZIP si quieres conservarlo.",
"Projekte werden automatisch gespeichert – im Browser oder (Chrome/Edge) direkt in einem Ordner auf dem PC.": "Los proyectos se guardan automáticamente: en el navegador o (Chrome/Edge) directamente en una carpeta del PC.",
"Speicherplatz im Browser ist voll.": "El almacenamiento del navegador está lleno.",
"Tipp: In Chrome oder Edge kannst du auch direkt einen Projektordner auf dem PC öffnen.": "Consejo: en Chrome o Edge también puedes abrir directamente una carpeta de proyecto del PC.",
"Web-Version": "Versión web",
